using System.Collections.Generic;public class Solution{bool Ok(string s){int b=0;foreach(char c in s){if(c=='(')b++;else if(c==')'&&--b<0)return false;}return b==0;}public IList<string> RemoveInvalidParentheses(string s){var o=new List<string>();var q=new Queue<string>();var v=new HashSet<string>();q.Enqueue(s);v.Add(s);bool found=false;while(q.Count>0&&!found){int z=q.Count;while(z-->0){string x=q.Dequeue();if(Ok(x)){o.Add(x);found=true;}if(found)continue;for(int i=0;i<x.Length;i++)if(x[i]=='('||x[i]==')'){string y=x.Remove(i,1);if(v.Add(y))q.Enqueue(y);}}}return o;}}
